using Test, GravitationalWaveforms, StaticArrays, LinearAlgebra

# SEOBNRv5PHM post-Newtonian spin evolution (milestone P1) against pyseobnr 0.3.7's `prec_eqns_20102022`,
# `compute_quasiprecessing_PNdynamics_opt` and `build_splines_PN`. Reference data in test/data/phm_pn, generated by
# scripts/pyseobnr_phm_pn_reference.py. pyseobnr's own solution carries two floors this port cannot remove: its RHS
# renormalizes LN_hat in the solver state (the step-size-dependent projection leaves ~1e-5 differences vs the
# step -> 0 limit this port integrates), and its cubic spline through ~70-100 DOP853 nodes interpolates with
# errors up to ~1e-4 in the spin components.

const _PNG = GravitationalWaveforms
const _PN_DIR = joinpath(@__DIR__, "data", "phm_pn")

_pn_rows(f) = [parse.(Float64, split(l, ',')) for l in eachline(f) if !startswith(l, '#') && !isempty(l)]

function _pn_header(f)
    d = Dict{String,Any}()
    for m in eachmatch(r"(\w+)=(\[[^\]]*\]|\S+)", readline(f))
        d[m[1]] = m[2][1] == '[' ? parse.(Float64, split(m[2][2:end-1], ",")) : parse(Float64, m[2])
    end
    return d
end

@testset "SEOBNRv5PHM PN spin evolution vs pyseobnr ($tag)" for tag in ("q1.5_a", "q3_b", "q1_c", "q8_d")
    solf = joinpath(_PN_DIR, "pyseobnr037_phmpn_$(tag)_sol.csv")
    h = _pn_header(solf)
    m1, m2 = h["m1"], h["m2"]
    # translated right-hand side
    for r in _pn_rows(joinpath(_PN_DIR, "pyseobnr037_phmpn_$(tag)_rhs.csv"))
        d = _PNG._seobv5phm_pn_rhs(SVector{10}(r[1:10]), m1 * m2, m1, m2, m1, m2)
        @test maximum(abs.(d .- r[11:20]) ./ max.(abs.(r[11:20]), 1e-300)) < 1e-13
    end
    tab = _PNG.seobnrv5phm_pn_table(m1, m2, h["chi1"], h["chi2"], h["omega_ref"], h["omega_start"]; N = 256)
    @test _PNG._seobv5phm_pn_om(tab.x[tab.n], tab.p) ≈ _PNG._SEOBV5PHM_PN_OMEGA_MAX      # no early stop
    # state at pyseobnr's DOP853 nodes
    worst = 0.0
    for r in _pn_rows(solf)
        Lh, S1, S2 = _PNG.seobnrv5phm_pn_state(tab, r[11])
        worst = max(worst, norm(Lh - SVector(r[2], r[3], r[4]) / norm(SVector(r[2], r[3], r[4]))),
                    norm(S1 - SVector(r[5], r[6], r[7])) / m1^2, norm(S2 - SVector(r[8], r[9], r[10])) / m2^2)
    end
    @test worst < 5e-5
    # the 16 spline quantities the EOB dynamics read
    for r in _pn_rows(joinpath(_PN_DIR, "pyseobnr037_phmpn_$(tag)_spl.csv"))
        e = _PNG.seobnrv5phm_pn_everything(tab, r[1])
        @test maximum(abs.(e .- r[2:17])) < 1.5e-4
    end
end
